/**
 * Sprint 33R — Decision Support Response Draft Harness: fixtures.
 *
 * Scenario descriptors used by
 * `tests/playbook-engine-conversation-decision-support-response-draft-harness.test.mjs`. Each entry
 * documents one behavior this sprint must exhibit — some carry a `sourceCase` (a minimal
 * `{ caseId, routeKind, responseKind }` shape, exactly what a Sprint 32R response QA case assessment
 * already carries) that the test file feeds through the actual pipeline; others (e.g. "attempt to
 * enable X blocked") describe a config-level invariant the test file checks directly, and use neutral
 * placeholders for the fields that do not apply.
 *
 * This fixture never imports from `src/`, and is never imported by production code — it exists only
 * for this sprint's own test suite.
 */

export type DecisionSupportResponseDraftHarnessFixtureSourceCase = {
  caseId: string;
  routeKind: string;
  responseKind: string;
};

export type DecisionSupportResponseDraftHarnessFixtureCase = {
  id: string;
  scenario: string;
  draftKind: string;
  expectedDraftStatus: string;
  expectedQaStatus: string;
  expectedRiskLevel: string;
  expectedValid: boolean;
  expectedSafeForQualityEvaluation: boolean;
  expectedSafeForUserVisibleOutputNow: boolean;
  expectedSafeForProduction: boolean;
  expectedSideEffectsZero: boolean;
  expectedLeaksZero: boolean;
  notes: string;
  /** Present only for scenarios that build/validate a real synthetic draft. */
  sourceCase?: DecisionSupportResponseDraftHarnessFixtureSourceCase;
  /** Present only for the thirteen "attempt to enable X blocked" config scenarios. */
  configOverrideField?:
    | "allowUserVisibleOutput"
    | "allowProductionWiring"
    | "allowRouterChange"
    | "allowComposerChange"
    | "allowEndpointChange"
    | "allowFeatureFlag"
    | "allowRealPersistence"
    | "allowDbWrite"
    | "allowSupabaseWrite"
    | "allowExternalCalls"
    | "allowActionExecution"
    | "allowTaskCreation"
    | "allowEmailDraftCreation";
};

